Python JavaScript Java <pre><code>    # Fetch current metadata value from network
    metadata_path = (
        f'/metadata?sourceAddress={signer_address}'
        f'&amp;targetAddress={signer_address}'
        f'&amp;scopedMetadataKey={scoped_metadata_key:016X}'
        '&amp;metadataType=0'
    )
    print(f'Fetching current metadata from {metadata_path}')
    with urllib.request.urlopen(
        f'{NODE_URL}{metadata_path}') as response:
        response_json = json.loads(response.read().decode())

    # Get the metadata entry
    if not response_json['data']:
        raise RuntimeError('Metadata entry not found')
    metadata_entry = response_json['data'][0]['metadataEntry']
    current_value = bytes.fromhex(metadata_entry['value'])
    print(f'  Current value: {current_value.decode("utf8")}')
</code></pre> <pre><code>    // Fetch current metadata value from network
    const scopedKeyHex = scopedMetadataKey.toString(16)
        .toUpperCase().padStart(16, '0');
    const metadataPath = `/metadata?sourceAddress=${signerAddress}` +
        `&amp;targetAddress=${signerAddress}` +
        `&amp;scopedMetadataKey=${scopedKeyHex}` +
        '&amp;metadataType=0';
    console.log('Fetching current metadata from', metadataPath);
    const metadataResponse = await fetch(`${NODE_URL}${metadataPath}`);
    const metadataJSON = await metadataResponse.json();

    // Get the metadata entry
    if (!metadataJSON.data.length)
        throw new Error('Metadata entry not found');

    const metadataEntry = metadataJSON.data[0].metadataEntry;
    const currentValue = Buffer.from(metadataEntry.value, 'hex');
    console.log('  Current value:', currentValue.toString('utf8'));
</code></pre> <pre><code>        // Fetch current metadata value from network
        final String scopedKeyHex = "%016X".formatted(
            scopedMetadataKey);
        final String metadataPath = String.format(
            "/metadata?sourceAddress=%s&amp;targetAddress=%s"
                + "&amp;scopedMetadataKey=%s&amp;metadataType=0",
            signerAddress, signerAddress, scopedKeyHex);
        System.out.printf("Fetching current metadata from %s%n",
            metadataPath);
        final HttpRequest metadataRequest = HttpRequest.newBuilder(
            URI.create(nodeUrl + metadataPath)).GET().build();
        final HttpResponse&lt;String&gt; metadataResponse = HTTP_CLIENT.send(
            metadataRequest, BodyHandlers.ofString());
        final JsonNode metadataJson = JSON_MAPPER.readTree(
            metadataResponse.body());

        // Get the metadata entry
        final JsonNode metadataData = metadataJson.get("data");
        if (null == metadataData)
            throw new IOException(
                "Unexpected metadata response: " + metadataJson);

        if (metadataData.isEmpty())
            throw new IOException("Metadata entry not found");

        final JsonNode metadataEntry = metadataData.get(0)
            .get("metadataEntry");
        final byte[] currentValue = java.util.HexFormat.of()
            .parseHex(metadataEntry.get("value").asText());
        System.out.printf("  Current value: %s%n",
            new String(currentValue, StandardCharsets.UTF_8));
</code></pre> <p>To retrieve the current value of a metadata entry, the code uses the <code>/metadata</code> <code>GET</code> endpoint with filters for <code>sourceAddress</code>, <code>targetAddress</code>, <code>scopedMetadataKey</code>, and <code>metadataType</code> (<code>0</code> for account metadata).</p> <p>The endpoint returns the list of entries matching the filters, which in this case contains a single item.</p>

Python JavaScript Java <pre><code>    # XOR the current and new values
    new_value = 'bob'.encode('utf8')
    update_value = metadata_update_value(current_value, new_value)

    # Create the update transaction with XOR'd value
    update_embedded_tx = (
        facade.create_embedded_transaction_from_descriptor(
            {
                'type': 'account_metadata_transaction_v1',
                'target_address': signer_address,
                'scoped_metadata_key': scoped_metadata_key,
                # value_size_delta is the difference in length
                # (can be negative)
                'value_size_delta': len(new_value) - len(current_value),
                'value': update_value
            },
            signer_key_pair.public_key))
</code></pre> <pre><code>    // XOR the current and new values
    const newValue = new TextEncoder().encode('bob');
    const updateValue = metadataUpdateValue(currentValue, newValue);

    // Create the update transaction with XOR'd value
    const updateEmbeddedTx =
        facade.createEmbeddedTransactionFromTypedDescriptor(
            new descriptors.AccountMetadataTransactionV1Descriptor(
                signerAddress,
                scopedMetadataKey,
                // valueSizeDelta is the difference in length
                // (can be negative)
                newValue.length - currentValue.length,
                updateValue),
            signerKeyPair.publicKey);
</code></pre> <pre><code>        // XOR the current and new values
        final byte[] newValue = "bob".getBytes(StandardCharsets.UTF_8);
        final byte[] updateValue = Metadata.updateValue(
            currentValue, newValue);

        // Create the update transaction with XOR'd value
        final EmbeddedTransaction updateEmbeddedTx =
            facade.createEmbeddedTransactionFromTypedDescriptor(
                new AccountMetadataTransactionV1Descriptor(
                    signerAddress,
                    scopedMetadataKey,
                    newValue.length - currentValue.length,
                    updateValue),
                signerKeyPair.getPublicKey());
</code></pre> <p>Updating an existing metadata entry requires the current value, retrieved from the network as previously shown.</p> <p>To demonstrate updating metadata, the code changes the username from <code>alice</code> to <code>bob</code> by creating another 6251a85a-47d0-11ee-be56-0242ac120002:8171b8c8f89038d36bf2d7f36f5808ab:&lt;__None__&gt; transaction with the same scoped metadata key.</p> <p>Modifying an existing metadata value differs from creating a new one in that the updated value must be defined in terms of the current value, using the following fields:</p> <ul> <li> <p><code>value_size_delta</code><code>valueSizeDelta</code><code>valueSizeDelta</code>: The difference in length between the new and current values.     In this example, the delta is <code>-2</code> because <code>bob</code> (3 bytes) is two bytes shorter than <code>alice</code> (5 bytes).</p> </li> <li> <p><code>value</code><code>value</code><code>value</code>: The XOR'd bytes computed by comparing the current and new values byte-by-byte.</p> <p>The SDK provides a 6251a85a-47d0-11ee-be56-0242ac120002:c754d53d12b3bc5795443a6266605b82:&lt;__None__&gt;6251a85a-47d0-11ee-be56-0242ac120002:972fb01b36a0cf4eaaa231071ec95c87:&lt;__None__&gt;6251a85a-47d0-11ee-be56-0242ac120002:9be85fc05c2fa9dd6f708f155b7acc1f:&lt;__None__&gt; helper function that handles the XOR calculation. The XOR operation compares each byte: matching bytes become zero, and differing bytes capture the change.</p> </li> </ul> <p>Note that <code>value_size_delta</code><code>valueSizeDelta</code><code>valueSizeDelta</code> represents the difference in final value lengths (new vs current), not the length of the XOR'd bytes themselves.</p> <p>Deleting a metadata entry</p> <p>To delete a metadata entry, set <code>value_size_delta</code><code>valueSizeDelta</code><code>valueSizeDelta</code> to the negative of the current value length and provide the current value as <code>value</code><code>value</code><code>value</code>. The XOR produces an empty result, which removes the entry from the network.</p> <p>As with the initial metadata creation, this metadata modification is wrapped in an aggregate transaction and then signed and announced.</p>  Python JavaScript Java <pre><code>    # Build the aggregate for the update
    update_embedded_txs = [update_embedded_tx]
    update_tx = facade.create_transaction_from_descriptor(
        {
            'type': 'aggregate_complete_transaction_v3',
            'transactions_hash': facade.hash_embedded_transactions(
                update_embedded_txs),
            'transactions': update_embedded_txs
        },
        signer_key_pair.public_key,
        fee_multiplier,
        2 * 60 * 60)

    # Sign and announce the update
    signature = facade.sign_transaction(
        signer_key_pair, update_tx)
    update_payload = facade.transaction_factory.attach_signature(
        update_tx, signature)

    # Announce and wait for confirmation
    update_tx_hash = facade.hash_transaction(update_tx)
    print(f'Built aggregate transaction with hash: {update_tx_hash}')
    announce_transaction(update_payload, 'update transaction')
    wait_for_confirmation(update_tx_hash, 'update transaction')
</code></pre> <pre><code>    // Build the aggregate for the update
    const updateEmbeddedTxs = [updateEmbeddedTx];
    const updateTx = facade.createTransactionFromTypedDescriptor(
        new descriptors.AggregateCompleteTransactionV3Descriptor(
            facade.static.hashEmbeddedTransactions(updateEmbeddedTxs),
            updateEmbeddedTxs,
            undefined),
        signerKeyPair.publicKey,
        feeMultiplier,
        2 * 60 * 60);

    // Sign and announce the update
    const updateSignature = facade.signTransaction(
        signerKeyPair, updateTx);
    const updatePayload = facade.transactionFactory.static
        .attachSignature(updateTx, updateSignature);

    // Announce and wait for confirmation
    const updateTxHash =
        facade.hashTransaction(updateTx).toString();
    console.log(
        'Built aggregate transaction with hash:', updateTxHash);
    await announceTransaction(updatePayload, 'update transaction');
    await waitForConfirmation(updateTxHash, 'update transaction');
</code></pre> <pre><code>        // Build the aggregate for the update
        final List&lt;EmbeddedTransaction&gt; updateEmbeddedTxs =
            List.of(updateEmbeddedTx);
        final Transaction updateTx =
            facade.createTransactionFromTypedDescriptor(
                new AggregateCompleteTransactionV3Descriptor(
                    SymbolFacade.hashEmbeddedTransactions(
                        updateEmbeddedTxs),
                    updateEmbeddedTxs,
                    null),
                signerKeyPair.getPublicKey(),
                feeMultiplier,
                2 * 60 * 60);

        // Sign and announce the update
        final String updatePayload = SymbolTransactionFactory
            .attachSignature(updateTx,
                facade.signTransaction(signerKeyPair, updateTx));

        // Announce and wait for confirmation
        final String updateTxHash =
            facade.hashTransaction(updateTx).toString();
        System.out.printf(
            "Built aggregate transaction with hash: %s%n",
            updateTxHash);
        announceTransaction(updatePayload, "update transaction");
        waitForConfirmation(updateTxHash, "update transaction");
</code></pre>

