        for (final JsonNode entry : mosaicsInfo) {
            final JsonNode mosaic = entry.get("mosaic");
            final BigInteger mosaicId = new BigInteger(
                mosaic.get("id").asText(), 16);
            mosaicsMap.put(mosaicId, mosaic);
